/**
 * A tax exempt group is a reusable, named set of tax exemption rules that can be
 * applied to one or more customers. Instead of exempting each customer
 * individually, you create a group, such as "Resellers" or "Non-profits", give it
 * reduced or zero override rates, and then associate customers with it through their
 * contact tax details.
 *
 * When a customer that belongs to a tax exempt group checks out, tax calculation
 * resolves the group and applies its exemption, reporting the reduced tax as an
 * exempt amount in the tax breakdown.
 *
 * A group's override rates are stored per tax group and tax region on the
 * associated manual tax mappings, so exemptions are applied by the Wix manual tax
 * calculator.
 */
export interface TaxExemptGroup {
  /**
   * Tax exempt group ID.
   * @format GUID
   * @readonly
   */
  _id?: string | null;
  /**
   * Revision number, which increments by 1 each time the tax exempt group is updated.
   * To prevent conflicting changes,
   * the current revision must be passed when updating the tax exempt group.
   *
   * Ignored when creating a tax exempt group.
   * @readonly
   */
  revision?: string | null;
  /**
   * Date and time the tax exempt group was created.
   * @readonly
   */
  _createdDate?: Date | null;
  /**
   * Date and time the tax exempt group was updated.
   * @readonly
   */
  _updatedDate?: Date | null;
  /**
   * Tax exempt group name. For example, `Resellers` or `Non-profits`.
   * @minLength 1
   * @maxLength 200
   */
  name?: string | null;
  /**
   * Custom field data for the tax exempt group.
   *
   * [Extended fields](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/backend-extensions/schema-plugins/about-schema-plugin-extensions) must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
  /** Tags associated with the tax exempt group. */
  tags?: Tags;
}

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

